import {readFile,writeFile} from 'node:fs/promises';
import {fileURLToPath} from 'node:url';
import {resolve} from 'node:path';

// A deliberately fixed manifest: no npm dependency or remote source is needed
// to prepare the single-file Worker for Cloudflare's dashboard editor.
const modules=[
 {path:'../lib/trading212-model.mjs',name:'TTBrokerModel',exports:['number','summary','position','historyItem'],imports:[],bindings:''},
 {path:'./trading212-worker.mjs',name:'TTBrokerRelay',exports:['ROUTES','nextCursor','handle'],imports:["import {summary, position, historyItem} from '../lib/trading212-model.mjs';"],bindings:'const {summary,position,historyItem}=TTBrokerModel;'},
 {path:'../lib/trade-evidence-schema.js',name:'TTEvidenceSchema',exports:[],imports:[],bindings:'',result:'globalThis.TradeEvidenceSchema'},
 {path:'../lib/cloud-sync-model.mjs',name:'TTCloudModel',exports:['KEYS','merge','mergeRecord','validateValue','EvidenceCloud'],imports:["import './trade-evidence-schema.js';"],bindings:''},
 {path:'../lib/cloud-monitor.mjs',name:'TTCloudMonitor',exports:['MONITOR_KEY','HEARTBEAT_KEY','monitorScope','monitorRules','schedulerStatus','handleMonitor','runMonitors'],imports:[],bindings:''},
 {path:'./cloud-sync-worker.mjs',name:'TTCloudWorker',exports:['PROTOCOL','readiness','seal','unseal','verifyGoogle','handleCloud','runScheduled'],imports:["import {KEYS,validateValue} from '../lib/cloud-sync-model.mjs';","import {handle as brokerHandle} from './trading212-worker.mjs';","import {handleMonitor,runMonitors,schedulerStatus} from '../lib/cloud-monitor.mjs';"],bindings:'const {KEYS,validateValue}=TTCloudModel;const {handle:brokerHandle}=TTBrokerRelay;const {handleMonitor,runMonitors,schedulerStatus}=TTCloudMonitor;'}
];
export const destination=new URL('./cloud-sync-worker.bundle.mjs',import.meta.url);
export async function buildBundle(){
 const blocks=[];
 for(const m of modules){
  let source=await readFile(new URL(m.path,import.meta.url),'utf8');
  const imports=source.match(/^import .*;$/gm)||[],exports=[...source.matchAll(/^export (?:async )?(?:const|function) (\w+)/gm)].map(x=>x[1]);
  if(JSON.stringify(imports)!==JSON.stringify(m.imports)||exports.length!==m.exports.length||exports.some(x=>!m.exports.includes(x)))throw Error('Manifestul Workerului trebuie actualizat pentru '+m.path);
  source=source.replace(/^import .*;\n/gm,'').replace(/^export default .*;\n?/gm,'').replace(/^export (?=(?:async )?(?:const|function) )/gm,'');
  if(/^\s*(?:import|export)\b/m.test(source))throw Error('Modul incompatibil cu pachetul: '+m.path);
  blocks.push('const '+m.name+'=(()=>{\n'+m.bindings+'\n'+source+'\nreturn '+(m.result||'{'+m.exports.join(',')+'}')+';\n})();');
 }
 return '// Generated by node tools/cloud-sync-bundle.mjs. Edit the source modules, then rebuild.\n'+blocks.join('\n')+'\nexport const {PROTOCOL,readiness,seal,unseal,verifyGoogle,handleCloud,runScheduled}=TTCloudWorker;\nexport default {fetch(request,env){return handleCloud(request,env);},scheduled(controller,env,ctx){ctx.waitUntil(runScheduled(env));}};\n';
}
if(process.argv[1]&&resolve(process.argv[1])===fileURLToPath(import.meta.url)){
 const bundle=await buildBundle();
 if(process.argv.includes('--check')){if(await readFile(destination,'utf8')!==bundle)throw Error('Workerul pregătit pentru publicare nu este actualizat. Rulează node tools/cloud-sync-bundle.mjs.');console.log('Workerul de sincronizare este actualizat.');}
 else {await writeFile(destination,bundle);console.log('Pregătit: tools/cloud-sync-worker.bundle.mjs');}
}
